--- Composes Latin letter + combining mark sequences into single code points.
function M.nfc(s)
  if not s:find("\204", 1, true) then
    return s
  end
  return (s:gsub("(%a)(\204[\128-\191])", function(base, mark)
    return nfd_to_nfc[base .. mark]
  end))
end

return M
